-- ######## Window rules ########

-- General rule – disable blur for all windows.
-- (Using "class:.*" as a catch-all field since at least one field is required)
-- windowrule = no_blur on, match:class .*
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
  match = {
    class = "^(foot)$",
  },
  opacity = 0.95,
  no_blur = true
})

-- Uncomment to apply global transparency to all windows:
hl.window_rule({
  match = {
    class = ".*",
  },
  opacity = "0.89 override",
})

-- Floating
hl.window_rule({
  match = {
    class = "^(blueberry\\.py)$",
  },
  float = true,
})

hl.window_rule({
  match = {
    title = "^(floating-foot)$",
  },
  float = true,
  size = "(monitor_w*0.25) (monitor_h*0.4)",
  move = "cursor_x cursor_y",
})

hl.window_rule({
  match = {
    class = "^(blueman-sendto)$",
  },
  float = true,
  center = true,
  size = "(monitor_w*0.66) (monitor_h*0.66)",
