-- Tiling
hl.window_rule({
  match = {
    class = "^dev\\.warp\\.Warp$",
  },
  tile = true
})

hl.window_rule({
  match = {
    class = "^(steam)$",
  },
  tile = true
})

-- Picture-in-Picture
hl.window_rule({
  match = {
    title = "^([Pp]icture[-\\s]?[Ii]n[-\\s]?[Pp]icture)(.*)$",
  },
  float = true,
  keep_aspect_ratio = true,
  move = "((monitor_w*0.66)) ((monitor_h*0.66))",
  size = "(monitor_w*0.33) (monitor_h*0.33)",
  pin = true,
})

-- Dialog windows – float+center these windows.
hl.window_rule({
  match = {
    title = "^(Open File)(.*)$",
