-- --- Tearing ---
hl.window_rule({
  match = {
    title = ".*\\.exe",
  },
  immediate = true,
})

hl.window_rule({
  match = {
    class = "^(steam_app)",
  },
  immediate = true,
})

-- No shadow for tiled windows (matches windows that are not floating).
hl.window_rule({
  match = {
    float = 0,
  },
  no_shadow = true
})

-- ######## Layer rules ########
hl.layer_rule({
  match = { namespace = "match:class .*" },
  xray = true
})

-- layerrule = noanim, .*
hl.layer_rule({
  match = { namespace = "match:class walker" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "match:class selection" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "match:class overview" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "match:class anyrun" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "match:class indicator.*" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "match:class osk" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "match:class hyprpicker" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "ignore_alpha 0.6" },
  blur = true
})

hl.layer_rule({
  match = { namespace = "match:namespace noanim" },
  no_anim = true
})

hl.layer_rule({
  match = { namespace = "ignore_alpha 0" },
  blur = true
})

hl.layer_rule({
  match = { namespace = "ignore_alpha 0.5" },
  blur = true
})

hl.layer_rule({
  match = { namespace = "ignore_alpha 0.69" },
  blur = true
})

hl.layer_rule({
  match = { namespace = "match:namespace logout_dialog" },
  blur = true
})

-- Fullscreen
hl.window_rule({
  match = {
    class = "^(org.qutebrowser.qutebrowser)$",
